package main

import (
	"bytes"
	"encoding/base64"
	"fmt"
	"image"
	"image/color"
	"image/png"
)

func main() {
	img := image.NewRGBA(image.Rect(0, 0, 100, 100))
	for y := 0; y < 100; y++ {
		for x := 0; x < 100; x++ {
			img.Set(x, y, color.RGBA{uint8(x), uint8(y), 255, 255})
		}
	}
	var buf bytes.Buffer
	png.Encode(&buf, img)
	b64 := base64.StdEncoding.EncodeToString(buf.Bytes())

	// Print Kitty
	chunkSize := 4096
	for i := 0; i < len(b64); i += chunkSize {
		end := i + chunkSize
		m := 1
		if end >= len(b64) {
			end = len(b64)
			m = 0
		}
		if i == 0 {
			fmt.Printf("\x1b_Ga=T,f=100,m=%d;%s\x1b\\", m, b64[i:end])
		} else {
			fmt.Printf("\x1b_Gm=%d;%s\x1b\\", m, b64[i:end])
		}
	}
	fmt.Println()
}
EOF
go run test_kitty.go > kitty_test.bin
ls -lh kitty_test.bin
"}

