{"command":"cat <<'EOF' > build.sh
#!/bin/bash
go build -o executable main.go
EOF
chmod +x build.sh

cat <<'EOF' > main.go
package main

import (
	"bufio"
	"bytes"
	"encoding/base64"
	"encoding/json"
	"flag"
	"fmt"
	"image"
	"image/color"
	"image/draw"
	"image/png"
	"io"
	"net/http"
	"os"
	"os/signal"
	"strconv"
	"strings"
	"syscall"
	"time"
	"unsafe"
)

type Winsize struct {
	Row    uint16
	Col    uint16
	Xpixel uint16
	Ypixel uint16
}

var interval = flag.Duration("interval", time.Second, "When url is provided, defines the interval between fetches")
var rowsFlag = flag.Int("rows", 0, "Limits the height of the graph output.")
var steps = flag.Int("steps", 100, "Number of values to plot.")
var urlStr = flag.String("url", "", "URL to fetch every second. Read JSON objects from stdin if not specified.")

type PathSpec struct {
	Path    string
	Counter bool
	Marker  bool
	LastVal float64
	HasLast bool
	Values  []float64
}

type GraphSpec struct {
	Paths []*PathSpec
}

func abs(x int) int {
	if x < 0 {
		return -x
	}
	return x
}

func drawLine(img *image.RGBA, x0, y0, x1, y1 int, col color.Color) {
	dx := abs(x1 - x0)
	dy := -abs(y1 - y0)
	var sx, sy int
	if x0 < x1 {
		sx = 1
	} else {
		sx = -1
	}
	if y0 < y1 {
		sy = 1
	} else {
		sy = -1
	}
	err := dx + dy
	for {
		if x0 >= 0 && x0 < img.Bounds().Max.X && y0 >= 0 && y0 < img.Bounds().Max.Y {
			img.Set(x0, y0, col)
		}
		if x0 == x1 && y0 == y1 {
			break
		}
		e2 := 2 * err
		if e2 >= dy {
			err += dy
			x0 += sx
		}
		if e2 <= dx {
			err += dx
			y0 += sy
		}
	}
}

func resolvePath(m map[string]interface{}, path string) float64 {
	parts := strings.Split(path, ".")
	var current interface{} = m
	for _, p := range parts {
		if curMap, ok := current.(map[string]interface{}); ok {
			current = curMap[p]
		} else {
			return 0
		}
	}
	if v, ok := current.(float64); ok {
		return v
	}
	return 0
}

func encodeSixel(img image.Image) string {
	b := img.Bounds()
	w, h := b.Dx(), b.Dy()
	var buf bytes.Buffer
	buf.WriteString(fmt.Sprintf("\x1bPq\"1;1;%d;%d", w, h))
	buf.WriteString("#0;2;0;0;0") // Black background
	buf.WriteString("#1;2;0;45;85") // Blue

	for y := 0; y < h; y += 6 {
		buf.WriteString("#1")
		for x := 0; x < w; x++ {
			var mask byte
			for dy := 0; dy < 6 && y+dy < h; dy++ {
				r, _, _, a := img.At(x, y+dy).RGBA()
				if a > 0 && r < 32000 {
					mask |= (1 << dy)
				}
			}
			buf.WriteByte(mask + 63)
		}
		buf.WriteString("-")
	}
	buf.WriteString("\x1b\\")
	return buf.String()
}

func queryTerminal() (string, int, int) {
    termProg := os.Getenv("TERM_PROGRAM")
    termType := "unknown"
    cellWidth, cellHeight := 10, 20

    if termProg == "iTerm.app" {
        termType = "iterm2"
    } else {
        // Query Kitty
        fmt.Print("\x1b_Gi=1,a=q,t=d,f=24\x1b\\")
        // Query Sixel
        fmt.Print("\x1b[c")

        // Non-blocking read from /dev/tty
        f, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
        if err == nil {
            f.SetReadDeadline(time.Now().Add(time.Second))
            buf := make([]byte, 1024)
            n, _ := f.Read(buf)
            resp := string(buf[:n])
            if strings.Contains(resp, "_Gi=1;OK") {
                termType = "kitty"
            } else if strings.Contains(resp, "?62") || strings.Contains(resp, "c") {
                termType = "sixel"
            }
            f.Close()
        }
    }
    return termType, cellWidth, cellHeight
}

func main() {
	flag.Parse()

	args := flag.Args()
	if len(args) == 0 {
		fmt.Fprintln(os.Stderr, "Usage: jplot [OPTIONS] FIELD_SPEC [FIELD_SPEC...]")
		os.Exit(1)
	}

	var graphs []*GraphSpec
	for _, arg := range args {
		g := &GraphSpec{}
		paths := strings.Split(arg, "+")
		for _, p := range paths {
			ps := &PathSpec{}
			if strings.Contains(p, ":") {
				parts := strings.Split(p, ":")
				opts := strings.Split(parts[0], ",")
				for _, opt := range opts {
					if opt == "counter" {
						ps.Counter = true
					} else if opt == "marker" {
						ps.Marker = true
					}
				}
				ps.Path = parts[1]
			} else {
				ps.Path = p
			}
			g.Paths = append(g.Paths, ps)
		}
		graphs = append(graphs, g)
	}

    termType, cellWidth, cellHeight := queryTerminal()

	if termType == "unknown" {
		fmt.Fprintln(os.Stderr, "\033[cjplot:  iTerm2, Kitty, or DRCS Sixel graphics required")
		os.Exit(1)
	}

	ws := &Winsize{}
	syscall.Syscall(syscall.SYS_IOCTL, uintptr(1), syscall.TIOCGWINSZ, uintptr(unsafe.Pointer(ws)))

	cols := int(ws.Col)
	if cols == 0 { cols = 80 }

	rows := *rowsFlag
	if rows == 0 {
		rows = int(ws.Row)
		if rows == 0 { rows = 24 }
	}

	width := cols * cellWidth
	height := rows * cellHeight

	fmt.Print("\x1b[?25l")
	for i := 0; i < rows-1; i++ {
		fmt.Print("\r\n")
	}
	fmt.Printf("\x1b[%dA\x1b[s", rows)

	sigc := make(chan os.Signal, 1)
	signal.Notify(sigc, os.Interrupt, syscall.SIGTERM)
	go func() {
		<-sigc
		fmt.Printf("\x1b[u\x1b[?25h\x1b[%dB\r\n", rows)
		os.Exit(0)
	}()

	var scanner *bufio.Scanner
	if *urlStr == "" {
		scanner = bufio.NewScanner(os.Stdin)
	}

	for {
		var m map[string]interface{}
		var err error

		if *urlStr != "" {
			resp, err2 := http.Get(*urlStr)
			if err2 == nil {
				json.NewDecoder(resp.Body).Decode(&m)
				resp.Body.Close()
			}
			time.Sleep(*interval)
		} else {
			if !scanner.Scan() {
				break
			}
			err = json.Unmarshal(scanner.Bytes(), &m)
		}

		if err == nil && m != nil {
			for _, g := range graphs {
				for _, p := range g.Paths {
					v := resolvePath(m, p.Path)
					if p.Counter {
						if p.HasLast {
							diff := v - p.LastVal
							p.Values = append(p.Values, diff)
						}
						p.LastVal = v
						p.HasLast = true
					} else {
						p.Values = append(p.Values, v)
					}
					if len(p.Values) > *steps {
						p.Values = p.Values[1:]
					}
				}
			}

			img := image.NewRGBA(image.Rect(0, 0, width, height))
			draw.Draw(img, img.Bounds(), &image.Uniform{color.RGBA{255, 255, 255, 255}}, image.Point{}, draw.Src)

			colors := []color.Color{
				color.RGBA{0, 115, 217, 255}, // Blue
				color.RGBA{255, 65, 54, 255}, // Red
				color.RGBA{46, 204, 64, 255}, // Green
			}

			graphHeight := height / len(graphs)
			for i, g := range graphs {
				gy := i * graphHeight

				var minVal, maxVal float64
				first := true
				for _, p := range g.Paths {
					for _, v := range p.Values {
						if first || v < minVal { minVal = v }
						if first || v > maxVal { maxVal = v }
						first = false
					}
				}

				if maxVal == minVal { maxVal += 1 }

				for j, p := range g.Paths {
					col := colors[j%len(colors)]
					stepX := float64(width) / float64(*steps)
					if stepX == 0 { stepX = 1 }

					for k := 1; k < len(p.Values); k++ {
						x0 := int(float64(k-1) * stepX)
						y0 := gy + graphHeight - 1 - int((p.Values[k-1]-minVal)/(maxVal-minVal)*float64(graphHeight-1))
						x1 := int(float64(k) * stepX)
						y1 := gy + graphHeight - 1 - int((p.Values[k]-minVal)/(maxVal-minVal)*float64(graphHeight-1))
						drawLine(img, x0, y0, x1, y1, col)
					}
				}
			}

			fmt.Print("\x1b[u") // restore

			if termType == "iterm2" {
				var buf bytes.Buffer
				png.Encode(&buf, img)
				b64 := base64.StdEncoding.EncodeToString(buf.Bytes())
				fmt.Printf("\x1b]1337;File=preserveAspectRatio=1;width=%dpx;height=%dpx;inline=1:%s\x07", width, height, b64)
			} else if termType == "kitty" {
				var buf bytes.Buffer
				png.Encode(&buf, img)
				b64 := base64.StdEncoding.EncodeToString(buf.Bytes())
				chunkSize := 4096
				for i := 0; i < len(b64); i += chunkSize {
					end := i + chunkSize
					m := 1
					if end >= len(b64) {
						end = len(b64)
						m = 0
					}
					if i == 0 {
						fmt.Printf("\x1b_Ga=T,f=100,m=%d;%s\x1b\\", m, b64[i:end])
					} else {
						fmt.Printf("\x1b_Gm=%d;%s\x1b\\", m, b64[i:end])
					}
				}
