cat <<'EOF' > main.go
package main

import (
	"bufio"
	"bytes"
	"encoding/base64"
	"encoding/json"
	"flag"
	"fmt"
	"image"
	"image/color"
	"image/draw"
	"image/png"
	"io"
	"net/http"
	"os"
	"os/signal"
	"strconv"
	"strings"
	"syscall"
	"time"
	"unsafe"
)

type Winsize struct {
	Row    uint16
	Col    uint16
	Xpixel uint16
	Ypixel uint16
}

var interval = flag.Duration("interval", time.Second, "When url is provided, defines the interval between fetches")
var rowsFlag = flag.Int("rows", 0, "Limits the height of the graph output.")
var steps = flag.Int("steps", 100, "Number of values to plot.")
var urlStr = flag.String("url", "", "URL to fetch every second. Read JSON objects from stdin if not specified.")

type PathSpec struct {
	Path    string
	Counter bool
	Marker  bool
	LastVal float64
	HasLast bool
	Values  []float64
}

type GraphSpec struct {
	Paths []*PathSpec
}

func abs(x int) int {
	if x < 0 {
		return -x
	}
	return x
}

func drawLine(img *image.RGBA, x0, y0, x1, y1 int, col color.Color) {
	dx := abs(x1 - x0)
	dy := -abs(y1 - y0)
	var sx, sy int
	if x0 < x1 {
		sx = 1
	} else {
		sx = -1
	}
	if y0 < y1 {
		sy = 1
	} else {
		sy = -1
	}
	err := dx + dy
	for {
		if x0 >= 0 && x0 < img.Bounds().Max.X && y0 >= 0 && y0 < img.Bounds().Max.Y {
			img.Set(x0, y0, col)
		}
		if x0 == x1 && y0 == y1 {
			break
		}
		e2 := 2 * err
		if e2 >= dy {
			err += dy
			x0 += sx
		}
		if e2 <= dx {
			err += dx
			y0 += sy
		}
	}
}

func resolvePath(m map[string]interface{}, path string) float64 {
	parts := strings.Split(path, ".")
	var current interface{} = m
	for _, p := range parts {
		if curMap, ok := current.(map[string]interface{}); ok {
			current = curMap[p]
		} else {
			return 0
		}
	}
	if v, ok := current.(float64); ok {
		return v
	}
	return 0
}

func encodeSixel(img image.Image) string {
	b := img.Bounds()
	w, h := b.Dx(), b.Dy()
	var buf bytes.Buffer
	buf.WriteString(fmt.Sprintf("\x1bPq\"1;1;%d;%d", w, h))
	buf.WriteString("#0;2;0;0;0") // Black background
	buf.WriteString("#1;2;0;45;85") // Blue

	for y := 0; y < h; y += 6 {
		buf.WriteString("#1")
		for x := 0; x < w; x++ {
			var mask byte
			for dy := 0; dy < 6 && y+dy < h; dy++ {
				r, _, _, a := img.At(x, y+dy).RGBA()
				if a > 0 && r < 32000 {
					mask |= (1 << dy)
				}
			}
			buf.WriteByte(mask + 63)
		}
		buf.WriteString("-")
	}
	buf.WriteString("\x1b\\")
	return buf.String()
}

func queryTerminal() (string, int, int) {
    termProg := os.Getenv("TERM_PROGRAM")
    termType := "unknown"
    cellWidth, cellHeight := 10, 20

    if termProg == "iTerm.app" {
        termType = "iterm2"
    } else {
        // Query Kitty
        fmt.Print("\x1b_Gi=1,a=q,t=d,f=24\x1b\\")
        // Query Sixel
        fmt.Print("\x1b[c")

        // Non-blocking read from /dev/tty
        f, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
        if err == nil {
            f.SetReadDeadline(time.Now().Add(time.Second))
