            resp := string(buf[:n])
            if strings.Contains(resp, "_Gi=1;OK") {
                termType = "kitty"
            } else if strings.Contains(resp, "?62") || strings.Contains(resp, "c") {
                termType = "sixel"
            }
            f.Close()
        }
    }
    return termType, cellWidth, cellHeight
}

func main() {
	flag.Parse()

	args := flag.Args()
	if len(args) == 0 {
		fmt.Fprintln(os.Stderr, "Usage: jplot [OPTIONS] FIELD_SPEC [FIELD_SPEC...]")
		os.Exit(1)
	}

	var graphs []*GraphSpec
	for _, arg := range args {
		g := &GraphSpec{}
		paths := strings.Split(arg, "+")
		for _, p := range paths {
			ps := &PathSpec{}
			if strings.Contains(p, ":") {
				parts := strings.Split(p, ":")
				opts := strings.Split(parts[0], ",")
				for _, opt := range opts {
					if opt == "counter" {
						ps.Counter = true
					} else if opt == "marker" {
						ps.Marker = true
					}
				}
				ps.Path = parts[1]
			} else {
				ps.Path = p
			}
			g.Paths = append(g.Paths, ps)
		}
		graphs = append(graphs, g)
	}

    termType, cellWidth, cellHeight := queryTerminal()

	if termType == "unknown" {
		fmt.Fprintln(os.Stderr, "\033[cjplot:  iTerm2, Kitty, or DRCS Sixel graphics required")
		os.Exit(1)
	}

	ws := &Winsize{}
	syscall.Syscall(syscall.SYS_IOCTL, uintptr(1), syscall.TIOCGWINSZ, uintptr(unsafe.Pointer(ws)))

	cols := int(ws.Col)
	if cols == 0 { cols = 80 }

	rows := *rowsFlag
	if rows == 0 {
		rows = int(ws.Row)
		if rows == 0 { rows = 24 }
	}

	width := cols * cellWidth
	height := rows * cellHeight

	fmt.Print("\x1b[?25l")
	for i := 0; i < rows-1; i++ {
		fmt.Print("\r\n")
	}
	fmt.Printf("\x1b[%dA\x1b[s", rows)

	sigc := make(chan os.Signal, 1)
	signal.Notify(sigc, os.Interrupt, syscall.SIGTERM)
	go func() {
		<-sigc
		fmt.Printf("\x1b[u\x1b[?25h\x1b[%dB\r\n", rows)
		os.Exit(0)
	}()

	var scanner *bufio.Scanner
	if *urlStr == "" {
		scanner = bufio.NewScanner(os.Stdin)
	}

	for {
		var m map[string]interface{}
		var err error

		if *urlStr != "" {
			resp, err2 := http.Get(*urlStr)
			if err2 == nil {
				json.NewDecoder(resp.Body).Decode(&m)
				resp.Body.Close()
			}
			time.Sleep(*interval)
		} else {
			if !scanner.Scan() {
				break
			}
			err = json.Unmarshal(scanner.Bytes(), &m)
		}

		if err == nil && m != nil {
			for _, g := range graphs {
				for _, p := range g.Paths {
					v := resolvePath(m, p.Path)
					if p.Counter {
						if p.HasLast {
							diff := v - p.LastVal
							p.Values = append(p.Values, diff)
						}
						p.LastVal = v
						p.HasLast = true
					} else {
						p.Values = append(p.Values, v)
					}
					if len(p.Values) > *steps {
						p.Values = p.Values[1:]
					}
				}
			}

			img := image.NewRGBA(image.Rect(0, 0, width, height))
			draw.Draw(img, img.Bounds(), &image.Uniform{color.RGBA{255, 255, 255, 255}}, image.Point{}, draw.Src)

			colors := []color.Color{
				color.RGBA{0, 115, 217, 255}, // Blue
				color.RGBA{255, 65, 54, 255}, // Red
				color.RGBA{46, 204, 64, 255}, // Green
			}

			graphHeight := height / len(graphs)
			for i, g := range graphs {
				gy := i * graphHeight

				var minVal, maxVal float64
				first := true
				for _, p := range g.Paths {
					for _, v := range p.Values {
						if first || v < minVal { minVal = v }
						if first || v > maxVal { maxVal = v }
						first = false
					}
				}

				if maxVal == minVal { maxVal += 1 }

				for j, p := range g.Paths {
					col := colors[j%len(colors)]
					stepX := float64(width) / float64(*steps)
					if stepX == 0 { stepX = 1 }

					for k := 1; k < len(p.Values); k++ {
						x0 := int(float64(k-1) * stepX)
						y0 := gy + graphHeight - 1 - int((p.Values[k-1]-minVal)/(maxVal-minVal)*float64(graphHeight-1))
						x1 := int(float64(k) * stepX)
						y1 := gy + graphHeight - 1 - int((p.Values[k]-minVal)/(maxVal-minVal)*float64(graphHeight-1))
						drawLine(img, x0, y0, x1, y1, col)
					}
				}
			}

			fmt.Print("\x1b[u") // restore

			if termType == "iterm2" {
				var buf bytes.Buffer
				png.Encode(&buf, img)
				b64 := base64.StdEncoding.EncodeToString(buf.Bytes())
				fmt.Printf("\x1b]1337;File=preserveAspectRatio=1;width=%dpx;height=%dpx;inline=1:%s\x07", width, height, b64)
			} else if termType == "kitty" {
				var buf bytes.Buffer
				png.Encode(&buf, img)
				b64 := base64.StdEncoding.EncodeToString(buf.Bytes())
				chunkSize := 4096
				for i := 0; i < len(b64); i += chunkSize {
					end := i + chunkSize
					m := 1
					if end >= len(b64) {
						end = len(b64)
						m = 0
					}
					if i == 0 {
						fmt.Printf("\x1b_Ga=T,f=100,m=%d;%s\x1b\\", m, b64[i:end])
					} else {
						fmt.Printf("\x1b_Gm=%d;%s\x1b\\", m, b64[i:end])
					}
				}
			} else if termType == "sixel" {
				fmt.Print(encodeSixel(img))
			}

			fmt.Print("\x1b[s") // save
		}
	}

	fmt.Printf("\x1b[u\x1b[?25h\x1b[%dB\r\n", rows)
}
EOF
