				png.Encode(&buf, img)
				b64 := base64.StdEncoding.EncodeToString(buf.Bytes())
				chunkSize := 4096
				for i := 0; i < len(b64); i += chunkSize {
					end := i + chunkSize
					m := 1
					if end >= len(b64) {
						end = len(b64)
						m = 0
					}
					if i == 0 {
						fmt.Printf("\033_Ga=T,f=100,m=%d;%s\033\\", m, b64[i:end])
					} else {
						fmt.Printf("\033_Gm=%d;%s\033\\", m, b64[i:end])
					}
				}
			} else if termType == "sixel" {
				fmt.Print(encodeSixel(img))
			}

			fmt.Print("\033[s")
		}
	}

	fmt.Printf("\033[u\033[?25h\033[%dB\r\n", rows)
}
