	}
	buf.WriteString("\x1b\\")
	return buf.String()
}

func queryTerminal() (string, int, int) {
	termProg := os.Getenv("TERM_PROGRAM")
	termType := "unknown"
	cellWidth, cellHeight := 10, 20

	if termProg == "iTerm.app" || os.Getenv("TERM") == "xterm-kitty" {
		if termProg == "iTerm.app" {
			termType = "iterm2"
		} else {
			termType = "kitty"
		}
	} else {
		fmt.Print("\x1b_Gi=1,a=q,t=d,f=24\x1b\\")
		fmt.Print("\x1b[c")

		f, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
		if err == nil {
			f.SetReadDeadline(time.Now().Add(time.Second))
			buf := make([]byte, 1024)
			n, _ := f.Read(buf)
			resp := string(buf[:n])
			if strings.Contains(resp, "_Gi=1;OK") {
				termType = "kitty"
			} else if strings.Contains(resp, "?62") || strings.Contains(resp, "c") {
				termType = "sixel"
			}
			f.Close()
		} else {
            termType = "sixel" // fallback to sixel if reading fails
        }
	}
	return termType, cellWidth, cellHeight
}

func main() {
	flag.Usage = func() {
		fmt.Fprintf(os.Stderr, "Usage: jplot [OPTIONS] FIELD_SPEC [FIELD_SPEC...]:\n\n")
		fmt.Fprintf(os.Stderr, "OPTIONS:\n")
		flag.PrintDefaults()
		fmt.Fprintf(os.Stderr, "\nFIELD_SPEC: [<option>[,<option>...]:]path\n")
		fmt.Fprintf(os.Stderr, "  option:\n")
		fmt.Fprintf(os.Stderr, "    - counter: Computes the difference with the last value. The value must increase monotonically.\n")
		fmt.Fprintf(os.Stderr, "    - marker: When the value is none-zero, a vertical line is drawn.\n")
		fmt.Fprintf(os.Stderr, "  path:\n")
		fmt.Fprintf(os.Stderr, "    JSON field path (eg: field.sub-field).\n")
	}

	flag.Parse()

	args := flag.Args()
	if len(args) == 0 {
		flag.Usage()
		os.Exit(1)
	}

	var graphs []*GraphSpec
	for _, arg := range args {
		g := &GraphSpec{}
		paths := strings.Split(arg, "+")
		for _, p := range paths {
			ps := &PathSpec{}
			if strings.Contains(p, ":") {
				parts := strings.Split(p, ":")
				opts := strings.Split(parts[0], ",")
				for _, opt := range opts {
					if opt == "counter" {
						ps.Counter = true
					} else if opt == "marker" {
						ps.Marker = true
					}
				}
				ps.Path = parts[1]
			} else {
				ps.Path = p
			}
			g.Paths = append(g.Paths, ps)
		}
		graphs = append(graphs, g)
	}

	termType, cellWidth, cellHeight := queryTerminal()

	if termType == "unknown" {
		fmt.Fprintln(os.Stderr, "\033[cjplot:  iTerm2, Kitty, or DRCS Sixel graphics required")
		os.Exit(1)
	}

	ws := &Winsize{}
	syscall.Syscall(syscall.SYS_IOCTL, uintptr(1), syscall.TIOCGWINSZ, uintptr(unsafe.Pointer(ws)))

	cols := int(ws.Col)
	if cols == 0 {
		cols = 80
	}

	rows := *rowsFlag
	if rows == 0 {
		rows = int(ws.Row)
		if rows == 0 {
			rows = 24
		}
	}

	width := cols * cellWidth
	height := rows * cellHeight

	fmt.Print("\033[?25l")
	for i := 0; i < rows-1; i++ {
		fmt.Print("\r\n")
	}
	fmt.Printf("\033[%dA\033[s", rows)

	sigc := make(chan os.Signal, 1)
	signal.Notify(sigc, os.Interrupt, syscall.SIGTERM)
	go func() {
		<-sigc
		fmt.Printf("\033[u\033[?25h\033[%dB\r\n", rows)
		os.Exit(0)
	}()

	var scanner *bufio.Scanner
	if *urlStr == "" {
		scanner = bufio.NewScanner(os.Stdin)
	}

	for {
		var m map[string]interface{}
		var err error

		if *urlStr != "" {
			resp, err2 := http.Get(*urlStr)
			if err2 == nil {
				json.NewDecoder(resp.Body).Decode(&m)
				resp.Body.Close()
			}
			time.Sleep(*interval)
		} else {
			if !scanner.Scan() {
				break
			}
			err = json.Unmarshal(scanner.Bytes(), &m)
		}

		if err == nil && m != nil {
			for _, g := range graphs {
				for _, p := range g.Paths {
					v := resolvePath(m, p.Path)
					if p.Counter {
						if p.HasLast {
							diff := v - p.LastVal
							p.Values = append(p.Values, diff)
						}
						p.LastVal = v
						p.HasLast = true
					} else {
						p.Values = append(p.Values, v)
					}
					if len(p.Values) > *steps {
						p.Values = p.Values[1:]
					}
				}
			}

			img := image.NewRGBA(image.Rect(0, 0, width, height))
			draw.Draw(img, img.Bounds(), &image.Uniform{color.RGBA{255, 255, 255, 255}}, image.Point{}, draw.Src)

			colors := []color.Color{
				color.RGBA{0, 115, 217, 255},
				color.RGBA{255, 65, 54, 255},
				color.RGBA{46, 204, 64, 255},
			}

			graphHeight := height / len(graphs)
			for i, g := range graphs {
				gy := i * graphHeight

				var minVal, maxVal float64
				first := true
				for _, p := range g.Paths {
					for _, v := range p.Values {
						if first || v < minVal {
							minVal = v
						}
						if first || v > maxVal {
							maxVal = v
						}
						first = false
					}
				}

				if maxVal == minVal {
					maxVal += 1
				}

				for j, p := range g.Paths {
					col := colors[j%len(colors)]
					stepX := float64(width) / float64(*steps)
					if stepX == 0 {
						stepX = 1
					}

					for k := 1; k < len(p.Values); k++ {
						x0 := int(float64(k-1) * stepX)
						y0 := gy + graphHeight - 1 - int((p.Values[k-1]-minVal)/(maxVal-minVal)*float64(graphHeight-1))
						x1 := int(float64(k) * stepX)
						y1 := gy + graphHeight - 1 - int((p.Values[k]-minVal)/(maxVal-minVal)*float64(graphHeight-1))
						drawLine(img, x0, y0, x1, y1, col)
					}
				}
			}

			fmt.Print("\033[u")

			if termType == "iterm2" {
				var buf bytes.Buffer
				png.Encode(&buf, img)
				b64 := base64.StdEncoding.EncodeToString(buf.Bytes())
				fmt.Printf("\033]1337;File=preserveAspectRatio=1;width=%dpx;height=%dpx;inline=1:%s\007", width, height, b64)
			} else if termType == "kitty" {
				var buf bytes.Buffer
				png.Encode(&buf, img)
				b64 := base64.StdEncoding.EncodeToString(buf.Bytes())
				chunkSize := 4096
				for i := 0; i < len(b64); i += chunkSize {
					end := i + chunkSize
					m := 1
					if end >= len(b64) {
						end = len(b64)
						m = 0
					}
					if i == 0 {
						fmt.Printf("\033_Ga=T,f=100,m=%d;%s\033\\", m, b64[i:end])
					} else {
						fmt.Printf("\033_Gm=%d;%s\033\\", m, b64[i:end])
					}
				}
			} else if termType == "sixel" {
				fmt.Print(encodeSixel(img))
			}

			fmt.Print("\033[s")
		}
	}

	fmt.Printf("\033[u\033[?25h\033[%dB\r\n", rows)
}
